#!/usr/bin/env python3
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
PAGES=['agence-ia/index.html','agents-ia.html','agence-automatisation/index.html','agence-developpement-logiciel/index.html','agence-application-mobile/index.html','expertises/web-apps/index.html','expertises/saas/index.html','expertises/crm/index.html','expertises/sites-web/index.html']
ASSETS='<link rel="stylesheet" href="/service-diagnostic.css?v=1"><script defer src="/service-diagnostic.js?v=1"></script>'
SECTION='''<section class="service-diagnostic" aria-labelledby="diagnostic-title"><div class="service-diagnostic__shell"><div class="service-diagnostic__head"><p class="eyebrow">Diagnostic express · 2 minutes</p><h2 id="diagnostic-title">Quel projet vous ferait vraiment gagner du temps ?</h2><p>Répondez à quatre questions. Vous obtiendrez une première direction à discuter avec nous, sans estimation automatique ni promesse artificielle.</p></div><form class="service-quiz" data-service-quiz><div class="service-quiz__progress"><span data-progress-label>Question 1 sur 4</span><progress max="4" value="1" aria-label="Progression du diagnostic"></progress></div><fieldset data-step><legend>Quel est votre objectif principal ?</legend><div class="service-quiz__options"><label class="service-quiz__choice" tabindex="0"><input type="radio" name="goal" value="ia"><span>Exploiter l’intelligence artificielle</span></label><label class="service-quiz__choice" tabindex="0"><input type="radio" name="goal" value="automate"><span>Automatiser des tâches répétitives</span></label><label class="service-quiz__choice" tabindex="0"><input type="radio" name="goal" value="product"><span>Créer un outil ou une application</span></label><label class="service-quiz__choice" tabindex="0"><input type="radio" name="goal" value="website"><span>Créer ou refondre un site web</span></label></div><div class="service-quiz__actions"><button type="button" data-next>Continuer →</button></div></fieldset><fieldset data-step hidden><legend>Où en êtes-vous aujourd’hui ?</legend><div class="service-quiz__options"><label class="service-quiz__choice"><input type="radio" name="stage" value="idea"><span>J’ai une idée à cadrer</span></label><label class="service-quiz__choice"><input type="radio" name="stage" value="scattered"><span>Mes outils sont dispersés</span></label><label class="service-quiz__choice"><input type="radio" name="stage" value="existing"><span>Une solution existe déjà</span></label><label class="service-quiz__choice"><input type="radio" name="stage" value="blocked"><span>Un processus nous ralentit</span></label></div><div class="service-quiz__actions"><button type="button" data-back>← Retour</button><button type="button" data-next>Continuer →</button></div></fieldset><fieldset data-step hidden><legend>Qui utilisera principalement la solution ?</legend><div class="service-quiz__options"><label class="service-quiz__choice"><input type="radio" name="users" value="team"><span>Notre équipe</span></label><label class="service-quiz__choice"><input type="radio" name="users" value="clients"><span>Nos clients</span></label><label class="service-quiz__choice"><input type="radio" name="users" value="both"><span>L’équipe et les clients</span></label><label class="service-quiz__choice"><input type="radio" name="users" value="unknown"><span>Je dois encore le préciser</span></label></div><div class="service-quiz__actions"><button type="button" data-back>← Retour</button><button type="button" data-next>Continuer →</button></div></fieldset><fieldset data-step hidden><legend>Quel rythme correspond à votre projet ?</legend><div class="service-quiz__options"><label class="service-quiz__choice"><input type="radio" name="timing" value="explore"><span>J’explore les possibilités</span></label><label class="service-quiz__choice"><input type="radio" name="timing" value="quarter"><span>Je souhaite cadrer ce trimestre</span></label><label class="service-quiz__choice"><input type="radio" name="timing" value="soon"><span>Le besoin est déjà prioritaire</span></label><label class="service-quiz__choice"><input type="radio" name="timing" value="replace"><span>Je dois remplacer un outil</span></label></div><div class="service-quiz__actions"><button type="button" data-back>← Retour</button><button type="button" data-next>Voir ma direction →</button></div></fieldset><div class="service-quiz__result" data-result hidden aria-live="polite"><p class="eyebrow">Votre première direction</p><h3></h3><p></p><a href="/contact/">Transformer cette piste en projet ↗</a><button type="button" class="service-quiz__restart" data-restart>Recommencer</button></div></form></div></section>'''
for rel in PAGES:
    src=ROOT/rel
    text=src.read_text()
    if '/service-diagnostic.css' not in text:
        text=text.replace('</head>',ASSETS+'</head>',1)
    if 'class="service-diagnostic"' not in text:
        text=text.replace('<section class="service-faq"',SECTION+'<section class="service-faq"',1)
    src.write_text(text)
    dest=ROOT/'dist'/rel
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(text)
for name in ['service-diagnostic.css','service-diagnostic.js']:
    (ROOT/'dist'/name).write_text((ROOT/name).read_text())
